{
    "classes": [
        {
            "doc": "\nThis class defines the methods and properties that pertain to the definition of an extrude\nfeature. This class also provides properties for setting/getting the Profile and Operation\nof the extrude. The Profile and Operation are defined when the ExtrudeFeatures.createInput\nmethod is called so they do not exist as properties on this class.\n",
            "functions": [
                {
                    "doc": "Sets the extrusion extents option to 'Distance'",
                    "name": "setDistanceExtent"
                },
                {
                    "doc": "Sets the extrusion extents option to 'Two Side'",
                    "name": "setTwoSidesDistanceExtent"
                },
                {
                    "doc": "Sets the extrusion extents option to 'All' (i",
                    "name": "setAllExtent"
                },
                {
                    "doc": "Sets the extrusion Direction option to 'One Side' and the Extents option to 'To' (a specified face)\ntoEntity : The entity that defines the 'to' extent",
                    "name": "setOneSideToExtent"
                },
                {
                    "doc": "Set the extrusion Direction option to 'Two Side'",
                    "name": "setTwoSidesToExtent"
                },
                {
                    "doc": "Defines the extrusion to go in one direction from the profile",
                    "name": "setOneSideExtent"
                },
                {
                    "doc": "Defines the extrusion to go in both directions from the profile",
                    "name": "setTwoSidesExtent"
                },
                {
                    "doc": "Defines the extrusion to go symmetrically in both directions from the profile",
                    "name": "setSymmetricExtent"
                },
                {
                    "doc": "Changes the extrude feature to be a thin extrude",
                    "name": "setThinExtrude"
                }
            ],
            "name": "ExtrudeFeatureInput",
            "namespace": "adsk.fusion",
            "properties": [
                {
                    "doc": "Gets and sets the profiles or planar faces used to define the shape of the extrude",
                    "name": "profile"
                },
                {
                    "doc": "Gets and sets the type of operation performed by the extrusion",
                    "name": "operation"
                },
                {
                    "doc": "Gets and sets the taper angle of the extrusion",
                    "name": "taperAngle"
                },
                {
                    "doc": "In order for geometry to be transformed correctly, an Occurrence for creation needs to be\nspecified when the Extrusion is created based on geometry (e",
                    "name": "creationOccurrence"
                },
                {
                    "doc": "Specifies if the extrusion should be created as a solid or surface",
                    "name": "isSolid"
                },
                {
                    "doc": "When creating a feature that is owned by a base feature, set this property to the\nbase feature you want to associate the new feature with",
                    "name": "targetBaseFeature"
                },
                {
                    "doc": "Gets and sets the extent used to define the start of the extrusion",
                    "name": "startExtent"
                },
                {
                    "doc": "Gets the extent assigned for a single sided extrude or side one of a two-sided extrusion",
                    "name": "extentOne"
                },
                {
                    "doc": "Gets the extent assigned for side two of the extrusion",
                    "name": "extentTwo"
                },
                {
                    "doc": "Gets the value that will be used as the taper angle for a single sided extrusion or side one of a two-sided\nextrusion",
                    "name": "taperAngleOne"
                },
                {
                    "doc": "Gets the value that will be used as the taper angle for side two of a two-sided extrusion",
                    "name": "taperAngleTwo"
                },
                {
                    "doc": "Property that indicates if the extrusion is a single or two-sided extrusion",
                    "name": "hasTwoExtents"
                },
                {
                    "doc": "Gets and sets the list of bodies that will participate in the feature when the operation is a cut or intersection",
                    "name": "participantBodies"
                },
                {
                    "doc": "Sets or returns whether the extrude is a thin extrude",
                    "name": "isThinExtrude"
                },
                {
                    "doc": "Gets and sets the wall location for a one sided thin extrude or side one of a two sided thin extrud",
                    "name": "thinExtrudeWallLocationOne"
                },
                {
                    "doc": "Gets and sets the wall location for side two of a two sided thin extrud",
                    "name": "thinExtrudeWallLocationTwo"
                },
                {
                    "doc": "Gets and sets the wall thickness for a one sided thin extrude or side one of a two sided thin extrud",
                    "name": "thinExtrudeWallThicknessOne"
                },
                {
                    "doc": "Gets and sets the wall thickness for side two of a two sided thin extrud",
                    "name": "thinExtrudeWallThicknessTwo"
                }
            ],
            "type": "class"
        },
        {
            "doc": "\nUsed to gather and define the various inputs and settings needed to calculate interference. This\nobject is created using the Design.createInterferenceInput method.\n",
            "name": "InterferenceInput",
            "namespace": "adsk.fusion",
            "properties": [
                {
                    "doc": "Gets and set an ObjectCollection containing BRepBody and/or Occurrence entities that\nwill be used when checking for interference",
                    "name": "entities"
                },
                {
                    "doc": "Gets and sets whether any coincident faces in the input bodies are considered as interference\nor not",
                    "name": "areCoincidentFacesIncluded"
                }
            ],
            "type": "class"
        },
        {
            "doc": "Represents an occurrence of a component at any level within a subassembly.",
            "functions": [
                {
                    "doc": "Deletes the occurrence from the design",
                    "name": "deleteMe"
                },
                {
                    "doc": "Creates or returns a proxy for the native object\n- i",
                    "name": "createForAssemblyContext"
                },
                {
                    "doc": "Makes the occurrence the active edit target in the user interface",
                    "name": "activate"
                },
                {
                    "doc": "Moves this occurrence from its current component into the component owned by the specified occurrence",
                    "name": "moveToComponent"
                },
                {
                    "doc": "Returns the PhysicalProperties object that has properties for getting the area, density, mass, volume, moments, etc",
                    "name": "getPhysicalProperties"
                },
                {
                    "doc": "When the component this occurrence references is an external reference (the isReferencedComponent property returns true),\nthis will break the link and create a local Component that this occurrence will reference",
                    "name": "breakLink"
                },
                {
                    "doc": "Replaces this occurrence or all occurrences that reference the same external component with a new component",
                    "name": "replace"
                },
                {
                    "doc": "Returns the bounding box of the specified entity types within the occurrence",
                    "name": "boundingBox2"
                },
                {
                    "doc": "Changes which configuration is used for this occurrence",
                    "name": "switchConfiguration"
                },
                {
                    "doc": "Switches the configuration for this occurrence to the specified row, applying custom\nvalues that override specific column values and optional metadata such as name, part number,\nand description",
                    "name": "switchToCustomConfiguration"
                }
            ],
            "name": "Occurrence",
            "namespace": "adsk.fusion",
            "properties": [
                {
                    "doc": "This is the sourceComponent for the occurrence and is affected\nby the assembly context",
                    "name": "sourceComponent"
                },
                {
                    "doc": "Returns a read only list of child occurrences where only the occurrences\nin this occurrence's AssemblyContext are returned",
                    "name": "childOccurrences"
                },
                {
                    "doc": "The component this occurrence references",
                    "name": "component"
                },
                {
                    "doc": "The name of the occurrence",
                    "name": "name"
                },
                {
                    "doc": "The name of the occurrence, including the full path of occurrences as seen in the browser",
                    "name": "fullPathName"
                },
                {
                    "doc": "Read-write property that gets and sets the appearance override for this occurrence",
                    "name": "appearance"
                },
                {
                    "doc": "Gets and sets if the light bulb of this occurrence as displayed in the browser is on or off",
                    "name": "isLightBulbOn"
                },
                {
                    "doc": "Gets whether the occurrence is visible",
                    "name": "isVisible"
                },
                {
                    "doc": "Gets and sets the 3d matrix data that defines this occurrences orientation and\nposition in its assembly context",
                    "name": "transform"
                },
                {
                    "doc": "Returns the timeline object associated with the creation of this occurrence",
                    "name": "timelineObject"
                },
                {
                    "doc": "Returns the assembly occurrence (i",
                    "name": "assemblyContext"
                },
                {
                    "doc": "The NativeObject is the object outside the context of an assembly",
                    "name": "nativeObject"
                },
                {
                    "doc": "Gets and sets whether this occurrence is pinned or not",
                    "name": "isGrounded"
                },
                {
                    "doc": "Gets and sets whether this occurrence is selectable or not",
                    "name": "isSelectable"
                },
                {
                    "doc": "Gets and sets whether this occurrence is isolated in the UI",
                    "name": "isIsolated"
                },
                {
                    "doc": "Gets whether this occurrence is the active edit target in the user interface",
                    "name": "isActive"
                },
                {
                    "doc": "Returns the PhysicalProperties object that has properties for getting the area, density, mass, volume, moments, etc",
                    "name": "physicalProperties"
                },
                {
                    "doc": "Gets if this occurrence is referencing an external component",
                    "name": "isReferencedComponent"
                },
                {
                    "doc": "Returns the bounding box of this occurrence",
                    "name": "boundingBox"
                },
                {
                    "doc": "Returns the joints that affect the position of this occurrence",
                    "name": "joints"
                },
                {
                    "doc": "Returns the rigid groups that this occurrence is a member of",
                    "name": "rigidGroups"
                },
                {
                    "doc": "Returns the as-built joints that affect the position of this occurrence",
                    "name": "asBuiltJoints"
                },
                {
                    "doc": "Returns the collection of attributes associated with this face",
                    "name": "attributes"
                },
                {
                    "doc": "Returns the body proxies for the B-Rep bodies in the component referenced by this occurrence",
                    "name": "bRepBodies"
                },
                {
                    "doc": "The user can set an override opacity for components and these opacity overrides combine if\nchildren and parent components have overrides",
                    "name": "visibleOpacity"
                },
                {
                    "doc": "Returns a token for the Occurrence object",
                    "name": "entityToken"
                },
                {
                    "doc": "Gets and sets the 3d matrix data that defines this occurrences orientation and\nposition in its assembly context",
                    "name": "transform2"
                },
                {
                    "doc": "When the component this occurrence references is an external reference (the isReferencedComponent property returns true),\nthis will return the object that represents that reference",
                    "name": "documentReference"
                },
                {
                    "doc": "Returns a bounding box that tightly fits around all B-Rep bodies in the occurrence",
                    "name": "preciseBoundingBox"
                },
                {
                    "doc": "Returns an oriented bounding box that is best oriented to tightly fit all B-Rep bodies in the occurrence",
                    "name": "orientedMinimumBoundingBox"
                },
                {
                    "doc": "Returns if this occurrence represents a configuration or not",
                    "name": "isConfiguration"
                },
                {
                    "doc": "If this occurrence is a configuration, this property returns the row that defines it",
                    "name": "configurationRow"
                },
                {
                    "doc": "Returns the DataFile object that represents the specific version of the design used by this occurrence",
                    "name": "configuredDataFile"
                },
                {
                    "doc": "Gets and sets whether this occurrence is grounded to parent or not",
                    "name": "isGroundToParent"
                },
                {
                    "doc": "Gets and sets the initial position of the occurrence",
                    "name": "initialTransform"
                },
                {
                    "doc": "Gets whether this occurrence is valid for edit initial position",
                    "name": "isVaildForEditInitialPosition"
                },
                {
                    "doc": "Gets the DataComponent for the target component in the source component's document",
                    "name": "dataComponent"
                },
                {
                    "doc": "Returns if this occurrence is derived from another design",
                    "name": "isDerived"
                },
                {
                    "doc": "Returns the DeriveFeature if this occurrence is derived from another design",
                    "name": "deriveFeature"
                },
                {
                    "doc": "Returns the body proxies for the mesh bodies in the component referenced by this occurrence",
                    "name": "meshBodies"
                },
                {
                    "doc": "Returns the definition of this occurrence",
                    "name": "definition"
                }
            ],
            "type": "class"
        },
        {
            "doc": "\nThe collection of arcs in a sketch. This provides access to the existing\narcs and supports the methods to create new arcs.\n",
            "functions": [
                {
                    "doc": "Function that returns the specified sketch arc using an index into the collection",
                    "name": "item"
                },
                {
                    "doc": "Creates a sketch arc that is always parallel to the x-y plane of the sketch\nand is centered at the specified point",
                    "name": "addByCenterStartSweep"
                },
                {
                    "doc": "Creates a sketch arc that passes through the three points",
                    "name": "addByThreePoints"
                },
                {
                    "doc": "Creates a fillet between two sketch entities\nThe side (quadrant) the fillet is created on is determined by the points specified",
                    "name": "addFillet"
                },
                {
                    "doc": "Creates a sketch arc that is centered at the specified point and between the two input points",
                    "name": "addByCenterStartEnd"
                }
            ],
            "name": "SketchArcs",
            "namespace": "adsk.fusion",
            "properties": [
                {
                    "doc": "Returns the number of arcs in the sketch",
                    "name": "count"
                }
            ],
            "type": "class"
        },
        {
            "doc": "\nA collection of the dimensions in a sketch. This object also supports the methods to add\nnew sketch dimensions.\n",
            "functions": [
                {
                    "doc": "Function that returns the specified sketch dimension using an index into the\ncollection",
                    "name": "item"
                },
                {
                    "doc": "Creates a new linear dimension constraint between the two input entities",
                    "name": "addDistanceDimension"
                },
                {
                    "doc": "Creates a new linear dimension constraint between the two input entities",
                    "name": "addOffsetDimension"
                },
                {
                    "doc": "Creates a new angular dimension constraint between the two input lines",
                    "name": "addAngularDimension"
                },
                {
                    "doc": "Creates a new diameter dimension constraint on the arc or circle",
                    "name": "addDiameterDimension"
                },
                {
                    "doc": "Creates a new radial dimension constraint on the arc or circle",
                    "name": "addRadialDimension"
                },
                {
                    "doc": "Creates a new dimension constraint on the major radius of an ellipse",
                    "name": "addEllipseMajorRadiusDimension"
                },
                {
                    "doc": "Creates a new dimension constraint on the minor radius of an ellipse",
                    "name": "addEllipseMinorRadiusDimension"
                },
                {
                    "doc": "Creates a new dimension constraint between to concentric circles or arcs",
                    "name": "addConcentricCircleDimension"
                },
                {
                    "doc": "Creates a new linear dimension from between a line and circle or arc and a second circle or arc where\nthe dimension is to the tangent on the edge of the circle or arc",
                    "name": "addTangentDistanceDimension"
                },
                {
                    "doc": "Creates a new linear dimension showing the diameter where the first line acts as the center line\nand the second entity defines the size",
                    "name": "addLinearDiameterDimension"
                },
                {
                    "doc": "Creates a new linear dimension controlling the distance between a sketch point and the specified surface or point",
                    "name": "addDistanceBetweenPointAndSurfaceDimension"
                },
                {
                    "doc": "Creates a new linear dimension controlling the distance between a sketch line and the specified planar face or construction plane",
                    "name": "addDistanceBetweenLineAndPlanarSurfaceDimension"
                }
            ],
            "name": "SketchDimensions",
            "namespace": "adsk.fusion",
            "properties": [
                {
                    "doc": "Returns the number of sketch dimensions in the sketch",
                    "name": "count"
                }
            ],
            "type": "class"
        }
    ],
    "message": "API documentation query completed",
    "success": true
}
